Here's a pytest test suite for `slugify`. It covers the happy path plus the edge cases this implementation actually has (multiple spaces, leading/trailing spaces, empty input, non-string input).

```python
# test_slugify.py
import pytest

from slugify import slugify  # adjust import to match your module layout


class TestSlugifyBasics:
    def test_single_space_is_replaced_with_hyphen(self):
        assert slugify("hello world") == "hello-world"

    def test_output_is_lowercase(self):
        assert slugify("Hello World") == "hello-world"

    def test_mixed_case_and_multiple_words(self):
        assert slugify("The Quick Brown Fox") == "the-quick-brown-fox"

    def test_already_lowercase_passthrough(self):
        assert slugify("hello-world") == "hello-world"


class TestSlugifyEdgeCases:
    def test_empty_string_returns_empty_string(self):
        assert slugify("") == ""

    def test_no_spaces_only_lowercases(self):
        assert slugify("HELLO") == "hello"

    def test_multiple_consecutive_spaces_become_multiple_hyphens(self):
        # Note: this implementation does NOT collapse runs of whitespace.
        assert slugify("hello  world") == "hello--world"

    def test_leading_and_trailing_spaces_are_preserved_as_hyphens(self):
        # Note: no trimming happens.
        assert slugify(" hello world ") == "-hello-world-"

    def test_space_only_string(self):
        assert slugify(" ") == "-"

    def test_punctuation_is_left_untouched(self):
        assert slugify("Hello, World!") == "hello,-world!"

    def test_numbers_are_preserved(self):
        assert slugify("Version 2 Release") == "version-2-release"

    def test_unicode_letters_are_lowercased(self):
        assert slugify("HÉLLO Wörld") == "héllo-wörld"


class TestSlugifyProperties:
    @pytest.mark.parametrize(
        "raw",
        [
            "hello world",
            "  spaced  out  ",
            "MiXeD Case 123",
            "already-a-slug",
            "",
            "!@#$%",
        ],
    )
    def test_idempotent(self, raw):
        # The output never contains a space, so re-slugifying is a no-op.
        once = slugify(raw)
        assert slugify(once) == once


class TestSlugifyErrors:
    def test_non_string_input_raises_attribute_error(self):
        with pytest.raises(AttributeError):
            slugify(123)

    def test_none_raises_attribute_error(self):
        with pytest.raises(AttributeError):
            slugify(None)


# --- Tests that document behavior the current implementation GETS WRONG ---
# Uncomment these if you decide to harden the function (e.g. regex-based,
# collapsing runs of whitespace and stripping leading/trailing hyphens).

@pytest.mark.xfail(reason="Implementation does not collapse whitespace runs")
def test_whitespace_runs_are_collapsed():
    assert slugify("hello    world") == "hello-world"

@pytest.mark.xfail(reason="Implementation does not strip surrounding whitespace")
def test_surrounding_whitespace_is_stripped():
    assert slugify("  hello world  ") == "hello-world"

@pytest.mark.xfail(reason="Implementation only handles the literal space char")
def test_tabs_and_newlines_are_handled():
    assert slugify("hello\tworld") == "hello-world"
```

Notes on what's being pinned down:

- **The core contract** — lowercase, spaces → hyphens — is covered by the first class.
- **Documented quirks**: this one-liner only replaces the literal `' '` character, doesn't collapse repeated spaces, and doesn't trim. The tests assert that behavior rather than pretending otherwise, so they'll fail loudly if someone changes it later.
- **`xfail` tests** mark the improvements you'd probably want. Flip them to `assert` (and remove the marker) once you harden the function. A regex version like `re.sub(r"\s+", "-", s.strip().lower())` or `re.sub(r"[-\s]+", "-", s.strip().lower())` would make them pass.

If your module is laid out differently (e.g. the function lives in `utils.py`), just update the import line.
